%[text] # Visually inspect buildElevationProfileFromRoadGradeProfileBlock
model_name = "HarnessModel_CustomRoadGradeProfile";
block_path = model_name + "/Road";

load_system(model_name)
%[text] Set up the block parameters.
% Horizontal distance for vertical profile
set_param(block_path, x_vector = "[-1 0 1]")
set_param(block_path, x_vector_unit = "km")

% Road grade profile (percent)
set_param(block_path, grade_vector = "[-1 -1 -1]")

% Profile interpolation method
set_param(block_path, profile_interp_method = "simscape.enum.interpolation.smooth")

% Elevation at left most horizontal position
set_param(block_path, left_elevation = "10")
set_param(block_path, left_elevation_unit = "m")

% Initial horizontal position
set_param(block_path, initial_position = "-1")
set_param(block_path, initial_position_unit = "m")
%[text] Read the block parameters and visualize. Visually inspect that the result is consistent with the above parameter settings. (Validation of values should be performed in the unit test.)
% !inspection-target
refined_data = buildElevationProfileFromRoadGradeProfileBlock( ...
  block_path, ...
  InterpolationInterval = simscape.Value(0.5, "m") );

plotElevationAndRoadGradeProfiles( ... %[output:group:764d2f2a] %[output:48ebfcde]
  DataSource = "table", ... %[output:48ebfcde]
  ProfileTable = refined_data ) %[output:group:764d2f2a] %[output:48ebfcde]
